<?php $taxonomy=is_array($question['taxonomy']??null)?$question['taxonomy']:[];$used=(int)($question['timesUsed']??0);$correct=(int)($question['timesCorrect']??0); ?><div class="ui-page-detail" data-ui-archetype="detail"><section class="page-header"><div><p class="eyebrow">Question inspector</p><h1><?= htmlspecialchars((string)($question['question']??'Question')) ?></h1><p>Review content, classification, and usage before editing.</p></div><a class="button" href="/question-editor/edit?id=<?= urlencode((string)($question['id']??'')) ?>">Edit question</a></section><section class="card"><h2>Question summary</h2><div class="ui-metadata-grid"><?php foreach(['id'=>'ID','status'=>'Status','difficulty'=>'Difficulty','source'=>'Source'] as $key=>$name): ?><?php if(isset($question[$key])&&trim((string)$question[$key])!==''): ?><div class="ui-metadata-item"><small><?= $name ?></small><strong><?= htmlspecialchars((string)$question[$key]) ?></strong></div><?php endif; ?><?php endforeach; ?></div></section><section class="card"><h2>Taxonomy</h2><div class="chip-list"><?php foreach(['board_id'=>'Board','subject_id'=>'Subject','domain_id'=>'Domain','topic_id'=>'Topic','concept_id'=>'Concept'] as $key=>$name): ?><?php if(isset($taxonomy[$key])&&trim((string)$taxonomy[$key])!==''): ?><span class="chip"><small><?= $name ?></small> <?= htmlspecialchars((string)$taxonomy[$key]) ?></span><?php endif; ?><?php endforeach; ?><?php if(!$taxonomy||!array_filter($taxonomy)): ?><p class="muted-note">Not classified</p><?php endif; ?></div></section><section class="card"><h2>Usage &amp; performance</h2><div class="ui-metadata-grid"><div class="ui-metadata-item"><small>Times used</small><strong><?= $used ?></strong></div><div class="ui-metadata-item"><small>Correct</small><strong><?= $correct ?></strong></div><div class="ui-metadata-item"><small>Incorrect</small><strong><?= (int)($question['timesIncorrect']??0) ?></strong></div><div class="ui-metadata-item"><small>Accuracy</small><strong><?= $used>0?round($correct/$used*100):0 ?>%</strong></div></div></section><p><a href="/question-inspector">Back to inspector</a></p></div>
